import { voxClient } from './client'

export type VoxSuggestion = {
  id: string
  type: 'action' | 'opportunity' | 'connection' | 'reminder'
  title: string
  description?: string
  confidence: number
  actionPayload?: Record<string, unknown>
}

export const voxSuggestions = {
  async getSuggestions(context: {
    tenantId: string
    userId: string
    projectId?: string
    objectiveId?: string
  }): Promise<VoxSuggestion[]> {
    return voxClient.fetch<VoxSuggestion[]>('/suggestions', {
      method: 'POST',
      body: JSON.stringify(context),
    })
  },
}
